import {GEOAPIFY_API_KEY} from './places-config.js';
import {countryName,canonicalRegion} from './geography.js';
const ENDPOINT='https://api.geoapify.com/v1/geocode/reverse',CACHE_KEY='nth-region-labels-v1',BUDGET_KEY='nth-region-usage-v1';
const pointKey=p=>Number.isFinite(p?.lat)&&Math.abs(p.lat)<=90&&Number.isFinite(p?.lng)&&Math.abs(p.lng)<=180?`${p.lat.toFixed(6)},${p.lng.toFixed(6)}`:null;
const clean=(v,max)=>typeof v==='string'?v.replace(/[\u0000-\u001f\u007f]/g,' ').trim().slice(0,max):'';
export function regionLabels(payload){const p=payload?.results?.[0]??payload?.features?.[0]?.properties;if(!p||typeof p!=='object')throw Error('No country/state found here. Choose the labels manually.');const country=countryName(p.country_code)||clean(p.country,80),region=canonicalRegion(country,clean(p.state,100),clean(p.state_code,12));if(!country)throw Error('No country/state found here. Choose the labels manually.');return {country,region};}
export function createRegionLookup({fetcher=globalThis.fetch,storage,network=globalThis.navigator,now=Date.now,timeoutMs=10000,minInterval=1000,wait=ms=>new Promise(r=>setTimeout(r,ms)),apiKey=GEOAPIFY_API_KEY}={}){
 const cache=new Map(),pending=new Map();let queue=Promise.resolve(),last=0,budget={day:'',count:0};
 try{for(const row of JSON.parse(storage?.getItem(CACHE_KEY)??'[]').slice(-100))if(Array.isArray(row)&&/^[-\d.]+,[-\d.]+$/.test(row[0])&&typeof row[1]?.country==='string'&&typeof row[1]?.region==='string')cache.set(row[0],{country:clean(row[1].country,80),region:clean(row[1].region,100)});const saved=JSON.parse(storage?.getItem(BUDGET_KEY)??'null');if(saved&&typeof saved.day==='string'&&Number.isInteger(saved.count)&&saved.count>=0)budget=saved;}catch{}
 const persist=(key,value)=>{try{storage?.setItem(key,JSON.stringify(value));}catch{}};
 return {lookup(point,{isCurrent=()=>true}={}){const key=pointKey(point);if(!key)return Promise.reject(Error('Choose valid coordinates first.'));if(cache.has(key))return Promise.resolve({...cache.get(key)});const existing=pending.get(key);if(existing){existing.gates.push(isCurrent);return existing.promise.then(v=>({...v}));}
  const entry={gates:[isCurrent]},alive=()=>entry.gates.some(g=>{try{return g();}catch{return false;}});const cancelled=()=>{if(!alive())throw Object.assign(Error('Lookup cancelled.'),{name:'AbortError'});};
  entry.promise=queue.then(async()=>{cancelled();if(network?.onLine===false)throw Error('Offline. Select a country and state/province below.');if(!apiKey)throw Error('Online region lookup is unavailable. Select labels manually.');await wait(Math.max(0,last+minInterval-now()));cancelled();const day=new Date(now()).toISOString().slice(0,10);if(budget.day!==day)budget={day,count:0};if(budget.count>=100)throw Error('Region lookup is paused for today. Select the labels manually.');budget.count++;persist(BUDGET_KEY,budget);last=now();
   const controller=new AbortController();let timer;try{const timeout=new Promise((_,reject)=>{timer=setTimeout(()=>{controller.abort();reject(Error('Region lookup timed out. Choose labels manually or try again.'));},timeoutMs);});const url=new URL(ENDPOINT);for(const [k,v]of Object.entries({lat:point.lat,lon:point.lng,type:'state',format:'json',lang:'en',limit:1,apiKey}))url.searchParams.set(k,String(v));const response=await Promise.race([fetcher(url.href,{signal:controller.signal,credentials:'omit',redirect:'error',referrerPolicy:'no-referrer',cache:'no-store',headers:{Accept:'application/json'}}),timeout]);if(!response.ok)throw Error('Country/state lookup is unavailable. Choose labels manually.');const raw=await Promise.race([response.text(),timeout]);if(new TextEncoder().encode(raw).length>65536)throw Error('Region lookup returned too much data. Choose labels manually.');const labels=regionLabels(JSON.parse(raw));cache.set(key,labels);while(cache.size>100)cache.delete(cache.keys().next().value);persist(CACHE_KEY,[...cache]);return labels;}finally{clearTimeout(timer);}
  });queue=entry.promise.catch(()=>{});pending.set(key,entry);entry.promise.finally(()=>pending.delete(key)).catch(()=>{});return entry.promise.then(v=>({...v}));
 }};
}
